  'call 0x2222222222222222222222222222222222222222') case "$3" in getMinDelay*) echo 86400;; hasRole*) if [[ "${ROLE_DRIFT:-}" == true && "$4" != "0x$(printf '00%.0s' {1..32})" && "$5" != 0x0000000000000000000000000000000000000000 ]]; then echo false; elif [[ "$4" == "0x$(printf '00%.0s' {1..32})" && "$5" == 0x2222222222222222222222222222222222222222 ]]; then echo true; elif [[ "$4" == "0x$(printf '00%.0s' {1..32})" || "$5" == 0x0000000000000000000000000000000000000000 ]]; then echo false; else echo true; fi;; hashOperationBatch*) echo 0xbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb;; isOperationDone*) [[ -e "$EXECUTED_MARKER" ]] && echo true || echo false;; isOperationPending*|isOperationReady*) [[ -e "$EXECUTED_MARKER" || -e "$CANCELLED_MARKER" ]] && echo false || echo true;; esac;;
